#include <iostream>
#include <string>
class MyClass {
public:
    int value;
    MyClass(int v) : value(v) {}  // Constructor for copy-initialization
    MyClass(const MyClass&) { std::cout << "Copy constructor called" << std::endl; }  // Non-trivial copy
};
int main() {
    MyClass obj1(10);  // lvalue of class type
    int obj2 = 20;    // Different type (int)
    auto result = (obj2 > 15) ? obj1 : MyClass(5);  // Ternary: lvalue vs prvalue, triggers conversion
    std::cout << result.value << std::endl;  // Uses temporary if conversion occurs
    return 0;
}
